-- =============================================================================
-- city_geo: city -> lat/lng crosswalk for the map radius/proximity search (#151).
-- Non-sensitive public reference data (US Census places). Generated from the
-- frontend crosswalk (fa-web-app/src/lib/geo/city-crosswalk.json).
-- Keys are normalized: city_norm = lower(trim(city)), state = upper 2-letter.
-- Idempotent: CREATE IF NOT EXISTS + INSERT ... ON CONFLICT DO NOTHING.
-- =============================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS city_geo (
    city_norm text NOT NULL,
    state     char(2) NOT NULL,
    lat       double precision NOT NULL,
    lng       double precision NOT NULL,
    PRIMARY KEY (city_norm, state)
);

-- Deny-all RLS like every other public table (backend bypasses with a
-- privileged role; the Supabase Data API gets no policy => no access).
ALTER TABLE city_geo ENABLE ROW LEVEL SECURITY;

CREATE INDEX IF NOT EXISTS idx_city_geo_state ON city_geo (state);

ON CONFLICT (city_norm, state) DO NOTHING;

ON CONFLICT (city_norm, state) DO NOTHING;

ON CONFLICT (city_norm, state) DO NOTHING;

ON CONFLICT (city_norm, state) DO NOTHING;

ON CONFLICT (city_norm, state) DO NOTHING;

ON CONFLICT (city_norm, state) DO NOTHING;

ON CONFLICT (city_norm, state) DO NOTHING;

COMMIT;
